import 'dart:async';

import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/foundation.dart';
import 'package:souq_akimi/widgets/ui.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:shared_preferences/shared_preferences.dart';

import 'app.dart';
import 'firebase_options.dart';
import 'providers/dependencies.dart';

/// Boots Firebase, loads the preferences store, then runs the app.
///
/// The options come from `lib/firebase_options.dart`, generated by
/// `flutterfire configure`. Passing them explicitly means the app does not
/// depend on the native config files being in the right place — but
/// `google-services.json` / `GoogleService-Info.plist` are still deployed so
/// the native side has them too.
Future<void> main() async {
  runZonedGuarded(
    () async {
      WidgetsFlutterBinding.ensureInitialized();
      _installErrorHandlers();

      await Firebase.initializeApp(
        options: DefaultFirebaseOptions.currentPlatform,
      );

      final preferences = await SharedPreferences.getInstance();

      runApp(
        ProviderScope(
          overrides: [sharedPreferencesProvider.overrideWithValue(preferences)],
          child: const SouqApp(),
        ),
      );
    },
    // Last line of defence: an error escaping a zone must never take the whole
    // app down mid-order. It is reported instead.
    (error, stack) => _report(error, stack, 'zone'),
  );
}

/// Replaces the red "Exception caught by widgets library" screen and stops
/// framework errors from being rethrown into the platform.
///
/// A student browsing a hostel corridor should see a tidy message and a way
/// back, not a stack trace — but developers still get the full detail in the
/// console, and any crash report sink added later hooks in here.
void _installErrorHandlers() {
  FlutterError.onError = (details) {
    FlutterError.presentError(details);
    _report(details.exception, details.stack, 'flutter');
  };
  PlatformDispatcher.instance.onError = (error, stack) {
    _report(error, stack, 'platform');
    return true;
  };
  ErrorWidget.builder = (details) =>
      _FriendlyCrash(message: kDebugMode ? '${details.exception}' : null);
}

void _report(Object error, StackTrace? stack, String origin) {
  // Always log. A release build has no other way to surface a bootstrap
  // failure, and a silent splash screen is impossible to diagnose remotely.
  debugPrint('Souq error ($origin): $error');
  if (stack != null) debugPrint('$stack');
}

/// Shown in place of a widget whose `build` threw.
class _FriendlyCrash extends StatelessWidget {
  const _FriendlyCrash({this.message});

  final String? message;

  @override
  Widget build(BuildContext context) {
    return Material(
      color: Theme.of(context).colorScheme.surface,
      child: Center(
        child: Padding(
          padding: const EdgeInsets.all(24),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(
                Icons.error_outline,
                size: 44,
                color: Theme.of(context).colorScheme.error,
              ),
              const SizedBox(height: 12),
              Text(
                'That part of the screen could not be shown.',
                textAlign: TextAlign.center,
                style: Theme.of(context).textTheme.titleMedium,
              ),
              if (message != null) ...[
                const SizedBox(height: 8),
                Text(
                  message!,
                  textAlign: TextAlign.center,
                  style: Theme.of(context).textTheme.bodySmall,
                ),
              ],
            ],
          ),
        ),
      ),
    );
  }
}
